\begin{lemma}
\label{ch03-lem-connection-evolves}
\source{chow-knopf-ricci-flow:page-0081}
\dcref{Lemma 3.2}
\group{variation-formulas}

If \(\partial_t g_{ij}=h_{ij}\), then the Levi-Civita connection varies by
\[
\partial_t\Gamma^k_{ij}
=\frac12 g^{k\ell}\bigl(\nabla_i h_{j\ell}+\nabla_j h_{i\ell}-\nabla_\ell h_{ij}\bigr).
\]
\end{lemma}

\begin{proof}
\source{chow-knopf-ricci-flow:page-0081}
\sketch In geodesic coordinates at a point, \(\Gamma^k_{ij}=0\) and \(\partial_i=\nabla_i\) at that point. Differentiating the coordinate formula for \(\Gamma^k_{ij}\) and then invoking tensoriality gives the result globally.
\end{proof}

